@import '../styles/keyframes-ritual.css';

.settings {
  position: absolute;
  top: 24px;
  left: 26px;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.04);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--motion-base);
  z-index: 5;
}

.settings:hover {
  background: var(--surface-hover-strong);
}

.content {
  max-width: 640px;
  width: 100%;
  text-align: center;
}

.greeting {
  font-family: var(--font-serif);
  font-weight: 300;
  font-size: 30px;
  line-height: 1.7;
  color: var(--color-fg-primary);
  margin: 0 0 14px;
}

.intro {
  font-size: 15px;
  color: var(--color-fg-subtle);
  line-height: 1.8;
  margin: 0 0 48px;
  white-space: pre-line;
}

.emptyInvite {
  font-family: var(--font-serif);
  font-weight: 300;
  font-size: 29px;
  line-height: 1.75;
  color: var(--color-fg-dormant);
  margin: 0 0 48px;
  white-space: pre-line;
}

.emptyHighlight {
  animation: brighten 0.4s ease 1.1s both;
}

.primaryRow {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 26px;
}

.resume {
  font-size: 14px;
  letter-spacing: 0.03em;
  padding: 14px 28px;
  border-color: var(--border-strong);
}

.footerRow {
  display: flex;
  gap: 26px;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}

