function initialIndex(): number {
  const requested = requestedQuestionNumber(route.query.q)
  if (Number.isFinite(requested) && requested >= 1) return Math.min(TOTAL, Math.trunc(requested)) - 1
  return Math.max(0, Math.min(TOTAL - 1, maxAnsweredIndex()))
}
function initialPhase(): Phase {
  const requested = requestedQuestionNumber(route.query.q)
  if (Number.isFinite(requested) && requested >= 1) return 'question'
  // 還沒有任何題目資料，或還停在第 1 題：走原本的反映段開場動畫。
  // 已經推進到第 1 題之後才重新整理：直接回到提問段，不要重播已經看過的反映文字。
  return maxAnsweredIndex() > 0 ? 'question' : 'reflection'
}

const currentIndex = ref(initialIndex())
const phase = ref<Phase>(initialPhase())
const draft = ref('')
const hintOpen = ref(false)
const reviseDialogOpen = ref(false)
const reviseTarget = ref<number | null>(null)

// 切換到不同探索（或同一路由帶不同 ?q）時，重新從查詢字串推算起始題號與階段
watch(
  () => `${route.params.id}:${route.query.q ?? ''}`,
  () => {
    currentIndex.value = initialIndex()
    phase.value = initialPhase()
    reviseDialogOpen.value = false
    reviseTarget.value = null
  }
)

// exploration 現在是非同步從後端載入（見 useExploration.ts），掛載當下 exploration.value 還是
// null，上面兩個 ref 的初始值只能先用「查無進度」推算。等 loading 轉為 false、真正的
// answers/history 進來後，要再算一次，不然重新整理頁面時畫面會卡在第 1 題，跟後端實際進度對不上。
watch(loading, isLoading => {
  if (isLoading) return
  currentIndex.value = initialIndex()
  phase.value = initialPhase()
  reviseDialogOpen.value = false
  reviseTarget.value = null
})

const currentAnswer = computed(() => exploration.value?.answers.find(a => a.questionIndex === currentIndex.value))
// 這題的內容是 AdvisingChatService 當輪動態產生的（見 useAdvisingConversation 的解析），
// 正常真實流程下進到這一題時一定已經有資料；解析失敗才會退回 rawReply／空字串。
const reflectionText = computed(() => currentAnswer.value?.reflection ?? currentAnswer.value?.rawReply ?? '')
const questionText = computed(() => currentAnswer.value?.question ?? currentAnswer.value?.rawReply ?? '')
const activeText = computed(() => (phase.value === 'reflection' ? reflectionText.value : questionText.value))

const { displayed, done } = useTypewriter({
  text: () => activeText.value,
  enabled: () => !reduceMotion.value,
  tickMs: () => settings.value.typingSpeedMs
})

// 探索場景由實景照片主導，關閉漸層光斑
useStageScene(
  () => toneForIndex(currentIndex.value),
  () => backdropForIndex(currentIndex.value),
  true
)

// 換題時載入該題已保存的回答
watch(
  currentIndex,
  () => {
    draft.value = currentAnswer.value?.text ?? ''
    hintOpen.value = false
  },
  { immediate: true }
)

function updateDraft(value: string) {
  draft.value = value
  setAnswer(currentIndex.value, value)
}

async function advance() {
  if (sending.value) return
  try {
    const { isFinal } = await send(draft.value)
    if (isFinal) {
      if (exploration.value) router.push(`/settle/${exploration.value.id}`)
      return
    }
    currentIndex.value += 1
    phase.value = 'reflection'
  } catch (err) {
    console.error('[ExplorationPage] advance failed', err)
    showToast(isQuotaError(err) ? t('common.quotaError') : t('exploration.sendError'))
  }
}

function requestRevise(target: number) {
  reviseTarget.value = target
  reviseDialogOpen.value = true
}

function goBack() {
  if (currentIndex.value === 0) {
    router.push('/topic')
    return
  }
  requestRevise(currentIndex.value - 1)
}

function closeReviseDialog() {
  reviseDialogOpen.value = false
  reviseTarget.value = null
}

async function confirmRevise() {
  const target = reviseTarget.value ?? currentIndex.value - 1
  try {
    await truncateAfter(target)
  } catch (err) {
    console.error('[ExplorationPage] truncate failed', err)
    showToast(t('exploration.sendError'))
    return
  }
  currentIndex.value = target
  phase.value = 'question'
  reviseDialogOpen.value = false
  reviseTarget.value = null
}

const progressNodes = computed(() => {
  const answers = exploration.value?.answers ?? []
  return Array.from({ length: TOTAL }, (_, i) => {
    const answer = answers.find(a => a.questionIndex === i)
    return {
      question: answer?.question ?? answer?.rawReply ?? '',
      answer: answer?.text,
      answered: Boolean(answer?.text)
    }
  })
})

const narrative = computed(
  () =>
    ({
      cool: t('exploration.stageCool'),
      mid: t('exploration.stageMid'),
      warm: t('exploration.stageWarm')
    })[toneForIndex(currentIndex.value)]
)

const revealed = computed(() => (reduceMotion.value ? activeText.value.length : displayed.value.length))
const typingDone = computed(() => reduceMotion.value || done.value)
</script>

<template>
  <Scene v-if="loading">{{ t('common.loading') }}</Scene>
  <Scene v-else-if="!exploration">{{ t('history.notFound') }}</Scene>
  <template v-else>
    <div :class="styles.narrative">{{ narrative }}</div>

    <div v-if="phase === 'reflection'" :class="styles.reflection" @click="phase = 'question'">
      <div :class="styles.reflectionInner">

