async function advance() {
  if (sending.value) return
  try {
    const { isFinal } = await send(draft.value)
    if (isFinal) {
      if (exploration.value) router.push(`/settle/${exploration.value.id}`)
      return
    }
    currentIndex.value += 1
    phase.value = 'reflection'
  } catch (err) {
    console.error('[ExplorationPage] advance failed', err)
    showToast(isQuotaError(err) ? t('common.quotaError') : t('exploration.sendError'))
  }
}

function requestRevise(target: number) {
  reviseTarget.value = target
  reviseDialogOpen.value = true
}

function goBack() {
  if (currentIndex.value === 0) {
    router.push('/topic')
    return
  }
  requestRevise(currentIndex.value - 1)
}

function closeReviseDialog() {
  reviseDialogOpen.value = false
  reviseTarget.value = null
}

async function confirmRevise() {
  const target = reviseTarget.value ?? currentIndex.value - 1
  try {
    await truncateAfter(target)
  } catch (err) {
    console.error('[ExplorationPage] truncate failed', err)
    showToast(t('exploration.sendError'))
    return
  }
  currentIndex.value = target
  phase.value = 'question'
  reviseDialogOpen.value = false
  reviseTarget.value = null
}

