/*
 * 共用進場 keyframes。
 * 注意：CSS Modules 會把 animation-name 連同 @keyframes 一起加上 scope，
 * 因此需要動畫的 *.module.css 必須以 @import 引入本檔，名稱才會對上。
 */
@keyframes sceneIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes riseIn {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: none; }
}

