input.new_string:
// 瀏覽（非送出）題目：夾在 0 ~ 目前進度之間，超過目前進度的題目還沒作答，不能瀏覽
function viewQuestion(index: number) {
  currentIndex.value = Math.max(0, Math.min(activeIndex.value, index))
  phase.value = 'question'
}

// 唯讀瀏覽時「下一題」單純往前翻頁（最多翻回目前進度），不會觸發送出
function handleNext() {
  if (readOnly.value) {
    viewQuestion(currentIndex.value + 1)
    return
  }
  void advance()
}

function jumpTo(index: number) {
  viewQuestion(index)
}

function resumeActive() {
  viewQuestion(activeIndex.value)
}

function goBack() {
  if (currentIndex.value === 0) {
    router.push('/topic')
    return
  }
  viewQuestion(currentIndex.value - 1)
}

// 滑鼠滾輪上下捲動切換上下題：往上只能瀏覽已作答的較早題目，往下最多翻回目前進度（不會觸發送出）
const wheelLocked = ref(false)

function onWheel(event: WheelEvent) {
  if (phase.value !== 'question' || !typingDone.value) return
  if ((event.target as HTMLElement).tagName === 'TEXTAREA') return
  if (wheelLocked.value || Math.abs(event.deltaY) < 10) return

  const delta = event.deltaY < 0 ? -1 : 1
  if (delta < 0 && currentIndex.value === 0) return
  if (delta > 0 && !readOnly.value) return

  event.preventDefault()
  viewQuestion(currentIndex.value + delta)
  wheelLocked.value = true
  window.setTimeout(() => {
    wheelLocked.value = false
  }, 380)
}

onMounted(() => window.addEventListener('wheel', onWheel, { passive: false }))
onUnmounted(() => window.removeEventListener('wheel', onWheel))

