  if ((event.target as HTMLElement).tagName === 'TEXTAREA') return
  if (wheelLocked.value || Math.abs(event.deltaY) < 10) return

  const delta = event.deltaY < 0 ? -1 : 1
  if (delta < 0 && currentIndex.value === 0) return
  if (delta > 0 && !readOnly.value) return

  event.preventDefault()
  viewQuestion(currentIndex.value + delta)
  wheelLocked.value = true
  window.setTimeout(() => {
    wheelLocked.value = false
  }, 380)
}

onMounted(() => window.addEventListener('wheel', onWheel, { passive: false }))
onUnmounted(() => window.removeEventListener('wheel', onWheel))

